SELECT TT.bizCode, TT.orderId, TT.paBizType, TT.PAY_TYPE, TT.PORTFOLIO_ID, TT.PORTFOLIO_NAME, TT.finprodId, TT.FINPROD_MARKET_ID, TT.finprodName, TT.SETTLE_DATE, TT.SETTLE_AMT, TT.CCY, TT.PURPOSE, TT.payAcctNo, TT.payAcctName, TT.recAcctNo, TT.recAcctName, TT.sendDate, TT.sendStatus, TT.orderRecStatus, TT.orderRetStatus, TT.PROFIT_TYPE, 'N' isDvp FROM ( SELECT IFNULL(T4.P_TOTLE_TRADE_ID, T4.TOTLE_TRADE_ID) bizCode, T10.ORDER_ID orderId, t5.PA_BUSS_TYPE paBizType, T10.PAY_TYPE, t4.PORTFOLIO_ID, t7.PORTFOLIO_NAME, t6.FINPROD_ID finprodId, t6.FINPROD_MARKET_ID, IFNULL(t6.FINPROD_ABBR, t6.FINPROD_NAME) finprodName, DATE_FORMAT(T10.SETTLE_DATE, '%Y-%m-%d') SETTLE_DATE, T10.SETTLE_AMT, T10.CCY,
T10.PURPOSE, T03.ACCT_NO payAcctNo, T03.ACCT_NAME payAcctName, T02.ACCT_NO recAcctNo, T02.ACCT_NAME recAcctName,
DATE_FORMAT(T10.SEND_DATE, '%Y-%m-%d HH24:mi:ss') sendDate, IFNULL(IPO.SEND_STATUS,'03') sendStatus, IPO.ORDER_REC_STATUS orderRecStatus, IPO.ORDER_RET_STATUS orderRetStatus, T6.PROFIT_TYPE, '${NO}' isDvp FROM TRD_FIN_PRODUCT_DEAL_TOTAL T4 LEFT JOIN PA_TRD_FIN_PRODUCT_DEAL_TOTAL T5 ON T4.TOTLE_TRADE_ID = T5.TOTLE_TRADE_ID LEFT JOIN FIN_PRODUCT T6 ON T4.FINPROD_ID = T6.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T7 ON T4.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN STL_PAY_ORDERS T10 ON T10.TRADE_ID = T4.TOTLE_TRADE_ID AND T10.IS_TOTAL_TRADE=#{YES} AND T10.ORDER_STATUS = #{ORDER_STATUS_01}
LEFT JOIN STL_CAPACCT_INFO T02 ON ((T10.PS = #{PS01} and T10.MY_ACCT_NO = T02.ACCT_NO) OR (T10.PS = #{PS02} and T10.COUNTER_ACCT_NO = T02.ACCT_NO)) LEFT JOIN STL_CAPACCT_INFO T03 ON ((T10.PS = #{PS02} and T10.MY_ACCT_NO = T03.ACCT_NO) OR (T10.PS = #{PS01} and T10.COUNTER_ACCT_NO = T03.ACCT_NO))
LEFT JOIN PTL_CAPACCT_INFO T11 ON T4.PORTFOLIO_ID = T11.PORTFOLIO_ID AND T11.ACCT_NO = T10.MY_ACCT_NO AND T11.CCY = T4.CCY LEFT JOIN FIN_PRODUCT_ADD FPA ON T4.CHL_ID = FPA.FINPROD_ID LEFT JOIN INF_PAY_ORDERS_STATUS IPO ON T10.ORDER_ID = IPO.ORDER_ID WHERE (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE03},
#{PA_BUSINESS_TYPE33},
#{PA_BUSINESS_TYPE17}, #{PA_BUSINESS_TYPE06}, #{PA_BUSINESS_TYPE01}, #{PA_BUSINESS_TYPE02}, #{PA_BUSINESS_TYPE05}, #{PA_BUSINESS_TYPE04}, #{PA_BUSINESS_TYPE07}, #{PA_BUSINESS_TYPE08}, #{PA_BUSINESS_TYPE35}, #{PA_BUSINESS_TYPE36}, #{PA_BUSINESS_TYPE11},
#{PA_BUSINESS_TYPE42}, #{PA_BUSINESS_TYPE43},
#{PA_BUSINESS_TYPE116},
#{PA_BUSINESS_TYPE37}, #{PA_BUSINESS_TYPE137}, #{PA_BUSINESS_TYPE138}, #{PA_BUSINESS_TYPE100}) OR (T5.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE52}, #{PA_BUSINESS_TYPE76}) AND FPA.PAY_TYPE = #{PAY_TYPE01}) OR (T4.FINPROD_TYPE2 IN (#{F29}, #{F30}, #{F10}, #{F11}, #{F12}, #{F13}, #{F14}) AND T10.PS = #{PS01}) )
AND T4.TRADE_STATUS = #{TRADE_STATUS_01} AND (T4.IS_CANCEL IS NULL OR T4.IS_CANCEL = #{NO}) AND T4.PORTFOLIO_ID IS NOT NULL AND T10.IS_NEED_SEND = #{YES}
null) or T4.PORTFOLIO_ID in (
#{item} )
#{item}
AND T10.PAY_TYPE = #{orderType}
AND IFNULL(IPO.SEND_STATUS,'03') = #{sendStatus}
AND IPO.ORDER_REC_STATUS = #{receiveStatus}
AND IPO.ORDER_RET_STATUS = #{dealStatus}
AND T10.SETTLE_DATE >= STR_TO_DATE(#{cashDateStart}, '%Y-%m-%d')
AND T10.SETTLE_DATE <= STR_TO_DATE(#{cashDateEnd}, '%Y-%m-%d')
#{item}
UNION ALL
SELECT CASE WHEN T8.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE65}, #{PA_BUSINESS_TYPE86}, #{PA_BUSINESS_TYPE87}, #{PA_BUSINESS_TYPE64}) THEN T10.ORDER_ID ELSE T4.TRADE_ID END bizCode, T10.ORDER_ID orderId, T8.PA_BUSS_TYPE paBizType, IFNULL(T10.PAY_TYPE, T12.PAY_TYPE) PAY_TYPE, T5.PORTFOLIO_ID, t7.PORTFOLIO_NAME, t6.FINPROD_ID finprodId, t6.FINPROD_MARKET_ID, IFNULL(t6.FINPROD_ABBR, t6.FINPROD_NAME) finprodName, DATE_FORMAT(IFNULL(T10.SETTLE_DATE, T12.SETTLE_DATE), '%Y-%m-%d') SETTLE_DATE, IFNULL(T10.SETTLE_AMT, T12.SETTLE_AMT) SETTLE_AMT, IFNULL(T10.CCY, T12.CCY) CCY,
if(T10.CCY= null, T12.PURPOSE, T10.PURPOSE) PURPOSE, if(T10.CCY= null, T032.ACCT_NO, T03.ACCT_NO) payAcctNo, if(T10.CCY= null, T032.ACCT_NAME, T03.ACCT_NAME) payAcctName, if(T10.CCY= null, T022.ACCT_NO, T02.ACCT_NO) recAcctNo, if(T10.CCY= null, T022.ACCT_NAME, T02.ACCT_NAME) recAcctName,
DATE_FORMAT(IFNULL(T10.SEND_DATE, T12.SEND_DATE), '%Y-%m-%d HH24:mi:ss') sendDate, IFNULL(IPO.SEND_STATUS,'03') sendStatus, IPO.ORDER_REC_STATUS orderRecStatus, IPO.ORDER_RET_STATUS orderRetStatus, T6.PROFIT_TYPE, '${NO}' isDvp FROM TRD_PRODUCT_DEAL T4 LEFT JOIN TRD_PRODUCT_DEAL_ADD T5 ON T4.TRADE_ID = T5.TRADE_ID LEFT JOIN PA_TRD_PRODUCT_DEAL T8 ON T4.TRADE_ID = T8.TRADE_ID LEFT JOIN FIN_PRODUCT T6 ON T4.FINPROD_ID = T6.FINPROD_ID LEFT JOIN PTL_PORTFOLIO T7 ON T5.PORTFOLIO_ID = T7.PORTFOLIO_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL T11 ON T4.TOTLE_TRADE_ID = T11.TOTLE_TRADE_ID LEFT JOIN STL_PAY_ORDERS T10 ON T10.TRADE_ID = T4.TRADE_ID AND T10.IS_TOTAL_TRADE=#{NO} AND T10.ORDER_STATUS = #{ORDER_STATUS_01}
LEFT JOIN STL_CAPACCT_INFO T02 ON ((T10.PS = #{PS01} and T10.MY_ACCT_NO = T02.ACCT_NO) OR (T10.PS = #{PS02} and T10.COUNTER_ACCT_NO = T02.ACCT_NO)) LEFT JOIN STL_CAPACCT_INFO T03 ON ((T10.PS = #{PS02} and T10.MY_ACCT_NO = T03.ACCT_NO) OR (T10.PS = #{PS01} and T10.COUNTER_ACCT_NO = T03.ACCT_NO))
LEFT JOIN STL_PAY_ORDERS T12 ON T11.TOTLE_TRADE_ID = T12.TRADE_ID AND T10.IS_TOTAL_TRADE=#{NO} AND T12.ORDER_STATUS = #{ORDER_STATUS_01}
LEFT JOIN STL_CAPACCT_INFO T022 ON ((T12.PS = #{PS01} and T12.MY_ACCT_NO = T022.ACCT_NO) OR (T12.PS = #{PS02} and T12.COUNTER_ACCT_NO = T022.ACCT_NO)) LEFT JOIN STL_CAPACCT_INFO T032 ON ((T12.PS = #{PS02} and T12.MY_ACCT_NO = T032.ACCT_NO) OR (T12.PS = #{PS01} and T12.COUNTER_ACCT_NO = T032.ACCT_NO))
LEFT JOIN FIN_PRODUCT_ADD FPA ON T4.CHL_ID = FPA.FINPROD_ID LEFT JOIN INF_PAY_ORDERS_STATUS IPO ON T10.ORDER_ID = IPO.ORDER_ID WHERE (T8.PA_BUSS_TYPE IN ( #{PA_BUSINESS_TYPE12}, #{PA_BUSINESS_TYPE16}, #{PA_BUSINESS_TYPE63}, #{PA_BUSINESS_TYPE65}, #{PA_BUSINESS_TYPE86}, #{PA_BUSINESS_TYPE64}, #{PA_BUSINESS_TYPE21}, #{PA_BUSINESS_TYPE22}, #{PA_BUSINESS_TYPE25}, #{PA_BUSINESS_TYPE97}, #{PA_BUSINESS_TYPE29}) OR (T8.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE09}) AND (T4.TRADE_MARKET IN (#{TP03}, #{TP04}) AND T4.TRADE_MARKET_MODE = #{STM_01})) OR (T8.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE09}) AND (T4.TRADE_MARKET IN (#{TP01}) AND T4.TRADE_MARKET_MODE = #{STM_01} AND T4.TRADE_PLAT in (#{SHARES_TRADE_PLATFORM_01},#{SHARES_TRADE_PLATFORM_99}))) OR (T8.PA_BUSS_TYPE IN (#{PA_BUSINESS_TYPE09}, #{PA_BUSINESS_TYPE12}, #{PA_BUSINESS_TYPE19}, #{PA_BUSINESS_TYPE75}) AND FPA.PAY_TYPE = #{PAY_TYPE01} ) OR (T4.FINPROD_TYPE2 IN (#{F29}, #{F30}, #{F10}, #{F11}, #{F12}, #{F13}, #{F14}) AND T10.PS = #{PS01}) )
AND T4.TRADE_STATUS = #{TRADE_STATUS_01} AND (T4.IS_CANCEL IS NULL OR T4.IS_CANCEL = #{NO}) AND T10.IS_NEED_SEND = #{YES}
#{item}
#{item}
AND IFNULL(T10.PAY_TYPE, T12.PAY_TYPE) = #{orderType}
AND IFNULL(IPO.SEND_STATUS,'03') = #{sendStatus}
AND IPO.ORDER_REC_STATUS = #{receiveStatus}
AND IPO.ORDER_RET_STATUS = #{dealStatus}
AND IFNULL(T10.SETTLE_DATE, T12.SETTLE_DATE) >= STR_TO_DATE(#{cashDateStart}, '%Y-%m-%d')
AND IFNULL(T10.SETTLE_DATE, T12.SETTLE_DATE) <= STR_TO_DATE(#{cashDateEnd}, '%Y-%m-%d')
#{item}
UNION ALL
SELECT T1.ORDER_ID bizCode, T1.ORDER_ID orderId, '${PA_BUSINESS_TYPE81}' paBizType, T1.PAY_TYPE, t1.PORTFOLIO_ID, t2.PORTFOLIO_NAME, NULL finprodId, NULL FINPROD_MARKET_ID, NULL finprodName, DATE_FORMAT(T1.SETTLE_DATE, '%Y-%m-%d') SETTLE_DATE, T1.SETTLE_AMT, T1.CCY,
T1.PURPOSE, T03.ACCT_NO payAcctNo, T03.ACCT_NAME payAcctName, T02.ACCT_NO recAcctNo, T02.ACCT_NAME recAcctName,
DATE_FORMAT(T1.SEND_DATE, '%Y-%m-%d HH24:mi:ss') sendDate, IFNULL(IPO.SEND_STATUS,'03') sendStatus, IPO.ORDER_REC_STATUS orderRecStatus, IPO.ORDER_RET_STATUS orderRetStatus, null PROFIT_TYPE, '${YES}' isDvp FROM STL_DVP_ORDERS T1
LEFT JOIN STL_CAPACCT_INFO T02 ON ((T1.PS = #{PS01} and T1.MY_ACCT_NO = T02.ACCT_NO) OR (T1.PS = #{PS02} and T1.COUNTER_ACCT_NO = T02.ACCT_NO)) LEFT JOIN STL_CAPACCT_INFO T03 ON ((T1.PS = #{PS02} and T1.MY_ACCT_NO = T03.ACCT_NO) OR (T1.PS = #{PS01} and T1.COUNTER_ACCT_NO = T03.ACCT_NO))
LEFT JOIN PTL_PORTFOLIO T2 ON T1.PORTFOLIO_ID = T2.PORTFOLIO_ID LEFT JOIN INF_PAY_ORDERS_STATUS IPO ON T1.ORDER_ID = IPO.ORDER_ID WHERE T1.IS_NEED_SEND = #{YES} AND T1.ORDER_STATUS = #{ORDER_STATUS_01}
#{item}
AND T1.PAY_TYPE = #{orderType}
AND IFNULL(IPO.SEND_STATUS,'03') = #{sendStatus}
AND IPO.ORDER_REC_STATUS = #{receiveStatus}
AND IPO.ORDER_RET_STATUS = #{dealStatus}
AND T1.SETTLE_DATE >= STR_TO_DATE(#{cashDateStart}, '%Y-%m-%d')
AND T1.SETTLE_DATE <= STR_TO_DATE(#{cashDateEnd}, '%Y-%m-%d')
UNION ALL
SELECT DISTINCT stl.ACT_ORDER_ID AS bizCode, 'OrderNewBuild001' as orderId, stl.BUSI_TYPE as paBizType, stl.PAY_TYPE , stl.PORTFOLIO_ID , ptl.PORTFOLIO_NAME , NULL finprodId, stl.PORTFOLIO_ID as FINPROD_MARKET_ID, ptl.PORTFOLIO_NAME as finprodName, DATE_FORMAT(stl.SETTLE_DATE, '%Y-%m-%d HH24:mi:ss') as settleDate, stl.SETTLE_AMT, stl.CCY, stl.PURPOSE, gat.ACCT_NO payAcctNo, gat.ACCT_NAME payAcctName, pay.ACCT_NO recAcctNo, pay.ACCT_NAME recAcctName, DATE_FORMAT(stl.SETTLE_DATE, '%Y-%m-%d HH24:mi:ss') sendDate, IFNULL(inf.SEND_STATUS,'03') sendStatus, inf.ORDER_REC_STATUS orderRecStatus, inf.ORDER_RET_STATUS orderRetStatus, null PROFIT_TYPE, '${YES}' isDvp
FROM STL_ACT_ORDER stl left join PTL_PORTFOLIO ptl on ptl.PORTFOLIO_ID=stl.PORTFOLIO_ID left join STL_CAPACCT_INFO pay on (stl.ps = '02' and stl.MY_ACCT_NO = pay.ACCT_NO) or (stl.ps = '01' and stl.COUNTER_ACCT_NO = pay.ACCT_NO) left join STL_CAPACCT_INFO gat on (stl.ps = '01' and stl.MY_ACCT_NO = gat.ACCT_NO) or (stl.ps = '02' and stl.COUNTER_ACCT_NO = gat.ACCT_NO) left join INF_PAY_ORDERS_STATUS inf on inf.ORDER_ID = stl.ACT_ORDER_ID Left JOIN STL_ACT_TRADE_MATCH stl2 ON stl.ACT_ORDER_ID = stl2.ACT_ORDER_ID Left JOIN TRD_FIN_PRODUCT_DEAL_TOTAL trd ON stl2.TRADE_ID = trd.TOTLE_TRADE_ID
WHERE stl.ORDER_STATUS = '01'
AND IFNULL(inf.SEND_STATUS,'03') = #{sendStatus}
and stl.PORTFOLIO_ID in #{item}
AND stl.SETTLE_DATE >= STR_TO_DATE(#{cashDateStart}, '%Y-%m-%d')
AND stl.SETTLE_DATE <= STR_TO_DATE(#{cashDateEnd}, '%Y-%m-%d')
) TT
#{item}
AND TT.PAY_TYPE = #{orderType}
AND TT.sendStatus = #{sendStatus}
AND TT.orderRecStatus = #{receiveStatus}
AND TT.orderRetStatus = #{dealStatus}
#{item}
